import numpy as np
from sklearn.base import BaseEstimator, OneToOneFeatureMixin, TransformerMixin
from sklearn.utils.validation import check_is_fitted, validate_data

class Winsorizer(OneToOneFeatureMixin, TransformerMixin, BaseEstimator):
    """Clip each feature to its 5th/95th percentile learned on training data."""
    def __init__(self, lower=0.05, upper=0.95):
        self.lower = lower            # store params unchanged, nothing else
        self.upper = upper

    def fit(self, X, y=None):
        X = validate_data(self, X, reset=True)
        self.low_, self.high_ = np.quantile(X, [self.lower, self.upper], axis=0)
        return self

    def transform(self, X):
        check_is_fitted(self)
        X = validate_data(self, X, reset=False)
        return np.clip(X, self.low_, self.high_)

X = np.arange(100.0).reshape(-1, 1)
w = Winsorizer(upper=0.9).fit(X)
print(w.transform([[-50.0], [500.0]]).ravel())  # [ 4.95 89.1 ]
print(w.get_params())                           # {'lower': 0.05, 'upper': 0.9}
